using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.Models;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Settings.Materials; public class CreateModel(ApplicationDbContext db,IPermissionService permissions):PageModel{[BindProperty]public Material Item{get;set;}=new();public Microsoft.AspNetCore.Mvc.Rendering.SelectList Units{get;private set;}=null!;public async Task<IActionResult> OnGetAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.Materials,PermissionAction.Add))return Forbid();await Load();return Page();}public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.Materials,PermissionAction.Add))return Forbid();if(!await db.Units.AnyAsync(x=>x.Id==Item.UnitOfMeasureId))ModelState.AddModelError("Item.UnitOfMeasureId","اختر وحدة صحيحة");if(!ModelState.IsValid){await Load();return Page();}db.Materials.Add(Item);await db.SaveChangesAsync();TempData["Message"]="تمت إضافة الخامة";return RedirectToPage("Index");}private async Task Load()=>Units=new Microsoft.AspNetCore.Mvc.Rendering.SelectList(await db.Units.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");}
